class Solution:
    def checkMove(self, board: List[List[str]], rMove: int, cMove: int, color: str) -> bool:
        opp = 'W' if color == 'B' else 'B'
        b = [row[:] for row in board]
        b[rMove][cMove] = color
        lines = []
        for i in range(8):
            lines.append([(i, j) for j in range(8)])
            lines.append([(j, i) for j in range(8)])
        for d in range(-7, 8):
            lines.append([(r, r - d) for r in range(8) if 0 <= r - d < 8])
            lines.append([(r, d + r) for r in range(8) if 0 <= d + r < 8])
        for line in lines:
            n = len(line)
            for i in range(n):
                if b[line[i][0]][line[i][1]] != color:
                    continue
                j = i + 1
                while j < n and b[line[j][0]][line[j][1]] == opp:
                    j += 1
                endHere = (line[i][0], line[i][1]) == (rMove, cMove)
                endThere = j < n and (line[j][0], line[j][1]) == (rMove, cMove)
                if (j < n and b[line[j][0]][line[j][1]] == color and j - i >= 2
                        and (endHere or endThere)):
                    return True
        return False

