class Solution {
public:
    bool checkMove(vector<vector<char>>& board, int rMove, int cMove, char color) {
        char opp = color == 'B' ? 'W' : 'B';
        vector<vector<char>> b = board;
        b[rMove][cMove] = color;
        vector<vector<pair<int, int>>> lines;
        for (int i = 0; i < 8; ++i) {
            vector<pair<int, int>> row, col;
            for (int j = 0; j < 8; ++j) {
                row.push_back({i, j});
                col.push_back({j, i});
            }
            lines.push_back(row);
            lines.push_back(col);
        }
        for (int d = -7; d <= 7; ++d) {
            vector<pair<int, int>> diag, anti;
            for (int r = 0; r < 8; ++r) {
                if (r - d >= 0 && r - d < 8) diag.push_back({r, r - d});
                if (d + r >= 0 && d + r < 8) anti.push_back({r, d + r});
            }
            lines.push_back(diag);
            lines.push_back(anti);
        }
        for (auto& line : lines) {
            int n = line.size();
            for (int i = 0; i < n; ++i) {
                if (b[line[i].first][line[i].second] != color) continue;
                int j = i + 1;
                while (j < n && b[line[j].first][line[j].second] == opp) ++j;
                bool endHere = line[i].first == rMove && line[i].second == cMove;
                bool endThere = j < n && line[j].first == rMove && line[j].second == cMove;
                if (j < n && b[line[j].first][line[j].second] == color && j - i >= 2
                    && (endHere || endThere))
                    return true;
            }
        }
        return false;
    }
};

