class Solution {
    public boolean checkMove(char[][] board, int rMove, int cMove, char color) {
        char opp = color == 'B' ? 'W' : 'B';
        char[][] b = new char[8][];
        for (int i = 0; i < 8; ++i) b[i] = board[i].clone();
        b[rMove][cMove] = color;
        List<int[][]> lines = new ArrayList<>();
        for (int i = 0; i < 8; ++i) {
            int[][] row = new int[8][], col = new int[8][];
            for (int j = 0; j < 8; ++j) {
                row[j] = new int[]{i, j};
                col[j] = new int[]{j, i};
            }
            lines.add(row);
            lines.add(col);
        }
        for (int d = -7; d <= 7; ++d) {
            List<int[]> diag = new ArrayList<>(), anti = new ArrayList<>();
            for (int r = 0; r < 8; ++r) {
                if (r - d >= 0 && r - d < 8) diag.add(new int[]{r, r - d});
                if (d + r >= 0 && d + r < 8) anti.add(new int[]{r, d + r});
            }
            lines.add(diag.toArray(new int[0][]));
            lines.add(anti.toArray(new int[0][]));
        }
        for (int[][] line : lines) {
            int n = line.length;
            for (int i = 0; i < n; ++i) {
                if (b[line[i][0]][line[i][1]] != color) continue;
                int j = i + 1;
                while (j < n && b[line[j][0]][line[j][1]] == opp) ++j;
                boolean endHere = line[i][0] == rMove && line[i][1] == cMove;
                boolean endThere = j < n && line[j][0] == rMove && line[j][1] == cMove;
                if (j < n && b[line[j][0]][line[j][1]] == color && j - i >= 2
                    && (endHere || endThere))
                    return true;
            }
        }
        return false;
    }
}

